function d({registerIndicator:m,nulls:p}){m({id:"oa-atrp",name:"Average True Range Percent (ATRP)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:14,min:1,max:5e3,step:1,tooltip:"Number of bars used for the ATR calculation."}],plots:[{key:"atrp",type:"line",title:"ATRP",style:{color:"#ffeb3b",lineWidth:2}}],calc(e,f){const a=Math.max(1,Math.floor(Number(f.length)||14)),b=1-1/a,g=1e-10,r=new Array(e.length).fill(NaN);let n=null,o=0,i=1;for(let t=0;t<e.length;t++){const c=Number(e[t].high),s=Number(e[t].low),l=Number(e[t].close);n===null&&(n=l);const N=c-s,y=Math.abs(c-n),A=Math.abs(s-n),u=Math.max(N,y,A);if(n=l,!Number.isFinite(u))continue;o=(o*(a-1)+u)/a,i*=b;const h=i>g?o/(1-i):o;!Number.isFinite(l)||l===0||Number.isFinite(h)&&(r[t]=h/l*100)}return{atrp:p(r)}}})}export{d as default};
